custom_fields.content:
[[[
  var soc = (states['sensor.luxpower_inverter_battery_battery_soc'] && states['sensor.luxpower_inverter_battery_battery_soc'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_battery_soc'].state : '0';
  var b_power = (states['sensor.luxpower_inverter_battery_battery_power'] && states['sensor.luxpower_inverter_battery_battery_power'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_battery_power'].state : '0';

  var b_chg_today = (states['sensor.luxpower_inverter_battery_charge_energy_today'] && states['sensor.luxpower_inverter_battery_charge_energy_today'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_charge_energy_today'].state : '0.0';
  var b_chg_total = (states['sensor.battery_charge_monthly'] && states['sensor.battery_charge_monthly'].state != 'unavailable') ? states['sensor.battery_charge_monthly'].state : ((states['sensor.luxpower_inverter_battery_charge_energy_total'] && states['sensor.luxpower_inverter_battery_charge_energy_total'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_charge_energy_total'].state : '0.0');
  var b_dis_today = (states['sensor.luxpower_inverter_battery_discharge_energy_today'] && states['sensor.luxpower_inverter_battery_discharge_energy_today'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_discharge_energy_today'].state : '0.0';
  var b_dis_total = (states['sensor.battery_discharge_monthly'] && states['sensor.battery_discharge_monthly'].state != 'unavailable') ? states['sensor.battery_discharge_monthly'].state : ((states['sensor.luxpower_inverter_battery_discharge_energy_total'] && states['sensor.luxpower_inverter_battery_discharge_energy_total'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_discharge_energy_total'].state : '0.0');

  // LOGIC ICON PIN ĐỘNG THEO DUNG LƯỢNG SOC (%)
  var soc_num = parseFloat(soc);
  var bat_num = parseFloat(b_power);
  var bat_icon = "mdi:battery-outline";

  if (bat_num < -5) {
    bat_icon = "mdi:battery-charging";
  } else if (soc_num >= 90) {
    bat_icon = "mdi:battery";
  } else if (soc_num >= 70) {
    bat_icon = "mdi:battery-70";
  } else if (soc_num >= 50) {
    bat_icon = "mdi:battery-50";
  } else if (soc_num >= 30) {
    bat_icon = "mdi:battery-30";
  } else if (soc_num >= 10) {
    bat_icon = "mdi:battery-10";
  } else {
    bat_icon = "mdi:battery-outline";
  }

  return `
    <div style="display: flex; flex-direction: column; justify-content: space-between; height: 100%; width: 100%; box-sizing: border-box;">
      <div>
        <!-- THANH TIÊU ĐỀ: PIN LƯU TRỮ -->
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; width: 100%;">
          <div style="display: flex; align-items: center; gap: 6px; background: rgba(209,158,255,0.15); padding: 4px 8px; border-radius: 10px; color: #d19eff; font-weight: 800; font-size: 11px;">
            <ha-icon icon="${bat_icon}" style="--mdc-icon-size: 15px; color: #d19eff;"></ha-icon> PIN LƯU TRỮ
          </div>
          <ha-icon icon="${bat_icon}" style="--mdc-icon-size: 24px; color: #d19eff; opacity: 0.6;"></ha-icon>
        </div>

        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 6px;">
          <div style="background: rgba(255, 255, 255, 0.04); border-radius: 10px; padding: 4px 6px; border: 1px solid rgba(209,158,255,0.12); text-align: center;">
            <div style="font-size: 8px; color: #d19eff; font-weight: 800; letter-spacing: 0.3px;">SẠC HÔM NAY</div>
            <div style="font-size: 16px; font-weight: 800; color: #fff; margin-top: 1px;">${b_chg_today} <span style="font-size: 9px; color: #aaa; font-weight: 400;">kWh</span></div>
            <div style="font-size: 8px; color: #777888; margin-top: 1px;">Tháng này: <span style="color:#aaa;">${b_chg_total} kWh</span></div>
          </div>
          <div style="background: rgba(255, 255, 255, 0.04); border-radius: 10px; padding: 4px 6px; border: 1px solid rgba(209,158,255,0.12); text-align: center;">
            <div style="font-size: 8px; color: #d19eff; font-weight: 800; letter-spacing: 0.3px;">XẢ HÔM NAY</div>
            <div style="font-size: 16px; font-weight: 800; color: #fff; margin-top: 1px;">${b_dis_today} <span style="font-size: 9px; color: #aaa; font-weight: 400;">kWh</span></div>
            <div style="font-size: 8px; color: #777888; margin-top: 1px;">Tháng này: <span style="color:#aaa;">${b_dis_total} kWh</span></div>
          </div>
        </div>
      </div>

      <!-- TRẠNG THÁI PIN CĂN GIỮA -->
      <div style="background: rgba(0, 0, 0, 0.4); border-radius: 12px; padding: 7px 12px; display: flex; align-items: center; justify-content: center; gap: 10px; width: 100%; box-sizing: border-box;">
        <div style="flex: 1; background: #2f1b42; height: 8px; border-radius: 4px; overflow: hidden;">
          <div style="width: ${soc}%; background: linear-gradient(90deg, #6c2bd9, #bc52ff); height: 100%; border-radius: 4px;"></div>
        </div>
        <div style="font-size: 17px; font-weight: 800; color: #d19eff;">${soc}%</div>
      </div>
    </div>
  `;
]]]

[[[
  var p_pv = parseFloat((states['sensor.luxpower_inverter_pv_pv_power'] && states['sensor.luxpower_inverter_pv_pv_power'].state != 'unavailable') ? states['sensor.luxpower_inverter_pv_pv_power'].state : '0');
  var p_grid = parseFloat((states['sensor.luxpower_inverter_grid_power_from_grid'] && states['sensor.luxpower_inverter_grid_power_from_grid'].state != 'unavailable') ? states['sensor.luxpower_inverter_grid_power_from_grid'].state : '0');
  var p_load = parseFloat((states['sensor.luxpower_inverter_load_power'] && states['sensor.luxpower_inverter_load_power'].state != 'unavailable') ? states['sensor.luxpower_inverter_load_power'].state : '0');
  var soc = (states['sensor.luxpower_inverter_battery_battery_soc'] && states['sensor.luxpower_inverter_battery_battery_soc'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_battery_soc'].state : '0';
  var b_power = (states['sensor.luxpower_inverter_battery_battery_power'] && states['sensor.luxpower_inverter_battery_battery_power'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_battery_power'].state : '0';
  var b_volt = (states['sensor.luxpower_inverter_battery_battery_voltage'] && states['sensor.luxpower_inverter_battery_battery_voltage'].state != 'unavailable') ? states['sensor.luxpower_inverter_battery_battery_voltage'].state : '0';

  var temp_state = states['sensor.luxpower_inverter_radiator_temperature'] || states['sensor.luxpower_radiator_temperature'];
  var inv_temp = (temp_state && temp_state.state != 'unavailable') ? temp_state.state : '0';

  // KIỂM TRA TRẠNG THÁI WI-FI ONLINE / OFFLINE
  var pv_st = states['sensor.luxpower_inverter_pv_pv_power'];
  var is_online = (pv_st && pv_st.state != 'unavailable' && pv_st.state != 'unknown');
  var wifi_icon = is_online ? "mdi:wifi" : "mdi:wifi-off";
  var wifi_text = is_online ? "Online" : "Offline";
  var wifi_color = is_online ? "#25d366" : "#ff3b30";

  var now = new Date().toLocaleTimeString('vi-VN', { hour12: false });

  var pv_path = "M 160 125 L 270 125 L 270 210 L 375 210";
  var grid_path = "M 840 125 L 730 125 L 730 210 L 625 210";
  var load_path = "M 625 290 L 730 290 L 730 375 L 840 375";

  var bat_num = parseFloat(b_power);
  var is_charging = bat_num < -5;
  var bat_path = is_charging 
    ? "M 375 290 L 270 290 L 270 375 L 160 375" 
    : "M 160 375 L 270 375 L 270 290 L 375 290";

  // LOGIC ICON PIN ĐỘNG VÀ CẠN RỖNG KHI 0%
  var soc_num = parseFloat(soc);
  var bat_icon = "mdi:battery-outline";

  if (is_charging) {
    bat_icon = "mdi:battery-charging";
  } else if (soc_num >= 90) {
    bat_icon = "mdi:battery";
  } else if (soc_num >= 70) {
    bat_icon = "mdi:battery-70";
  } else if (soc_num >= 50) {
    bat_icon = "mdi:battery-50";
  } else if (soc_num >= 30) {
    bat_icon = "mdi:battery-30";
  } else if (soc_num >= 10) {
    bat_icon = "mdi:battery-10";
  } else {
    bat_icon = "mdi:battery-outline";
  }

  var pv_dots = (p_pv > 5) ? `
    <circle r="8" fill="#25d366" filter="drop-shadow(0 0 8px #25d366)"><animateMotion path="${pv_path}" dur="2s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#25d366" filter="drop-shadow(0 0 8px #25d366)"><animateMotion path="${pv_path}" dur="2s" begin="0.66s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#25d366" filter="drop-shadow(0 0 8px #25d366)"><animateMotion path="${pv_path}" dur="2s" begin="1.33s" repeatCount="indefinite" /></circle>
  ` : '';

  var grid_dots = (p_grid > 5) ? `
    <circle r="8" fill="#4a90e2" filter="drop-shadow(0 0 8px #4a90e2)"><animateMotion path="${grid_path}" dur="2s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#4a90e2" filter="drop-shadow(0 0 8px #4a90e2)"><animateMotion path="${grid_path}" dur="2s" begin="0.66s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#4a90e2" filter="drop-shadow(0 0 8px #4a90e2)"><animateMotion path="${grid_path}" dur="2s" begin="1.33s" repeatCount="indefinite" /></circle>
  ` : '';

  var load_dots = (p_load > 5) ? `
    <circle r="8" fill="#ff5722" filter="drop-shadow(0 0 8px #ff5722)"><animateMotion path="${load_path}" dur="2s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#ff5722" filter="drop-shadow(0 0 8px #ff5722)"><animateMotion path="${load_path}" dur="2s" begin="0.66s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#ff5722" filter="drop-shadow(0 0 8px #ff5722)"><animateMotion path="${load_path}" dur="2s" begin="1.33s" repeatCount="indefinite" /></circle>
  ` : '';

  var bat_dots = (Math.abs(bat_num) > 5) ? `
    <circle r="8" fill="#bc52ff" filter="drop-shadow(0 0 8px #bc52ff)"><animateMotion path="${bat_path}" dur="2s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#bc52ff" filter="drop-shadow(0 0 8px #bc52ff)"><animateMotion path="${bat_path}" dur="2s" begin="0.66s" repeatCount="indefinite" /></circle>
    <circle r="8" fill="#bc52ff" filter="drop-shadow(0 0 8px #bc52ff)"><animateMotion path="${bat_path}" dur="2s" begin="1.33s" repeatCount="indefinite" /></circle>
  ` : '';

  return `
    <style>
      @keyframes flow-dash { 0% { stroke-dashoffset: 20; } 100% { stroke-dashoffset: 0; } }
      .active-flow { animation: flow-dash 1s linear infinite; }
    </style>

    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; width: 100%;">
      <div style="font-size: 14px; font-weight: 800; color: #fff; letter-spacing: 0.5px;">DÒNG NĂNG LƯỢNG</div>
      <div style="background: rgba(37,211,102,0.12); border: 1px solid rgba(37,211,102,0.3); padding: 3px 10px; border-radius: 16px; font-size: 10px; color: #25d366; font-weight: 700; display: flex; align-items: center; gap: 5px;">
        <span style="height: 5px; width: 5px; background-color: #25d366; border-radius: 50%; box-shadow: 0 0 5px #25d366;"></span> 
        Cập nhật: <span id="live-clock-mob">${now}</span>
      </div>
    </div>

    <!-- ĐỒNG HỒ NHẢY TỪNG GIÂY TRÊN MOBILE -->
    <img src="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7" style="display:none;" onload="
      if (!window.liveClockMobInterval) {
        window.liveClockMobInterval = setInterval(function() {
          var els = document.querySelectorAll('#live-clock-mob');
          var t = new Date().toLocaleTimeString('vi-VN', { hour12: false });
          els.forEach(function(el) { el.innerText = t; });
        }, 1000);
      }
    " />

    <div style="position: relative; height: 185px; width: 100%; display: flex; justify-content: space-between; align-items: center;">

      <svg viewBox="0 0 1000 500" preserveAspectRatio="none" style="position: absolute; width: 100%; height: 100%; top: 0; left: 0; pointer-events: none; z-index: 1;">
        <defs>
          <marker id="arr-green" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="6" markerHeight="6" orient="auto">
            <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#25d366"/>
          </marker>
          <marker id="arr-purple" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="6" markerHeight="6" orient="auto">
            <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#bc52ff"/>
          </marker>
          <marker id="arr-blue" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="6" markerHeight="6" orient="auto">
            <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#4a90e2"/>
          </marker>
          <marker id="arr-orange" viewBox="0 0 10 10" refX="6" refY="5" markerWidth="6" markerHeight="6" orient="auto">
            <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#ff5722"/>
          </marker>
        </defs>

        <path d="${pv_path}" stroke="#25d366" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke" fill="none" stroke-dasharray="6,6" marker-end="url(#arr-green)" class="${p_pv > 5 ? 'active-flow' : ''}" />
        <path d="${bat_path}" stroke="#bc52ff" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke" fill="none" stroke-dasharray="6,6" marker-end="url(#arr-purple)" class="${Math.abs(bat_num) > 5 ? 'active-flow' : ''}" />
        <path d="${grid_path}" stroke="#4a90e2" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke" fill="none" stroke-dasharray="6,6" marker-end="url(#arr-blue)" class="${p_grid > 5 ? 'active-flow' : ''}" />
        <path d="${load_path}" stroke="#ff5722" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke" fill="none" stroke-dasharray="6,6" marker-end="url(#arr-orange)" class="${p_load > 5 ? 'active-flow' : ''}" />

        ${pv_dots}
        ${bat_dots}
        ${grid_dots}
        ${load_dots}
      </svg>

      <!-- CỘT 1 (TRÁI): PV & PIN -->
      <div style="width: 35%; height: 100%; display: flex; flex-direction: column; justify-content: space-between; align-items: flex-start; z-index: 2;">
        <div style="display: flex; align-items: center; gap: 6px; margin-top: 10px;">
          <ha-icon icon="mdi:solar-power" style="--mdc-icon-size: 26px; color: #25d366;"></ha-icon>
          <div>
            <div style="font-size: 10px; color: #888;">PV</div>
            <div style="font-size: 12px; font-weight: 800; color: #25d366; line-height: 1.2;">${p_pv} <span style="font-size: 9px; color: #888; font-weight: 400;">W</span></div>
          </div>
        </div>
        <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 10px;">
          <ha-icon icon="${bat_icon}" style="--mdc-icon-size: 26px; color: #bc52ff;"></ha-icon>
          <div>
            <div style="font-size: 10px; color: #bc52ff; font-weight: 800;">${soc}%</div>
            <div style="font-size: 11px; font-weight: 800; color: #fff; line-height: 1.2;">${b_power} <span style="font-size: 9px; color: #aaa; font-weight: 400;">W</span></div>
            <div style="font-size: 9px; color: #aaa;">${b_volt} V</div>
          </div>
        </div>
      </div>

      <!-- CỘT 2 (GIỮA): LUXPOWER SNA PRO 6.5KW VỚI SÓNG WI-FI PHÍA TRÊN NẮP MÁY CAO THOÁNG TRÊN MOBILE -->
      <div style="width: 30%; height: 100%; display: flex; flex-direction: column; justify-content: center; align-items: center; z-index: 2; position: relative;">

        <!-- KHUNG MÔ HÌNH 3D LUXPOWER INVERTER MOBILE -->
        <div style="position: relative; max-width: 82px; width: 75%; height: 105px; background: linear-gradient(160deg, #ffffff 0%, #f0f2f5 70%, #dce0e6 100%); border-radius: 10px; border: 1px solid #dcdfe6; box-shadow: 0 10px 25px rgba(0,0,0,0.7), inset 0 2px 2px #ffffff, inset 0 -3px 5px rgba(0,0,0,0.15); display: flex; flex-direction: column; align-items: center; justify-content: space-between; padding: 6px 4px 4px 4px; box-sizing: border-box; margin-top: 16px;">

          <!-- HUY HIỆU SÓNG WI-FI ONLINE / OFFLINE NẰM NỔI PHÍA TRÊN NẮP MÁY CAO RÃI RÃI -->
          <div style="position: absolute; top: -24px; display: flex; align-items: center; gap: 3px; font-size: 8px; font-weight: 800; color: ${wifi_color}; background: rgba(0,0,0,0.6); padding: 1px 6px; border-radius: 8px; border: 1px solid ${wifi_color}; box-shadow: 0 0 6px ${wifi_color}50; white-space: nowrap;">
            <ha-icon icon="${wifi_icon}" style="--mdc-icon-size: 10px; color: ${wifi_color};"></ha-icon>
            <span>${wifi_text}</span>
          </div>

          <!-- LOGO HÃNG -->
          <div style="width: 100%; display: flex; align-items: center; justify-content: flex-start; gap: 2px; padding-left: 3px;">
            <span style="font-size: 7px; font-weight: 900; color: #1a252c; letter-spacing: -0.2px;">LUX<span style="color: #25d366;">⚡</span>POWER<span style="font-size: 5px; color: #666;">TEK</span></span>
          </div>

          <!-- MÀN HÌNH LCD KĨ THUẬT SỐ ĐEN BÓNG THỜI TRANG -->
          <div style="width: 58px; height: 38px; background: #080d14; border-radius: 5px; border: 1.5px solid #222; padding: 3px; display: flex; flex-direction: column; justify-content: space-between; align-items: center; box-shadow: inset 0 2px 4px rgba(0,0,0,0.8);">
            <div style="display: flex; align-items: center; gap: 3px;">
              <span style="height: 3px; width: 3px; background-color: #25d366; border-radius: 50%; box-shadow: 0 0 4px #25d366;"></span>
              <span style="font-size: 7px; color: #4a90e2; font-weight: 800;">SNA 6.5KW</span>
            </div>

            <!-- NHIỆT ĐỘ CẢM BIẾN LED PHÁT SÁNG TRÊN MÀN HÌNH -->
            <div style="font-size: 10px; font-weight: 800; color: #00ffcc; display: flex; align-items: center; gap: 2px; text-shadow: 0 0 5px rgba(0,255,204,0.6);">
              <ha-icon icon="mdi:thermometer" style="--mdc-icon-size: 11px; color: #00ffcc;"></ha-icon>
              <span>${inv_temp}°C</span>
            </div>

            <div style="display: flex; gap: 4px;">
              <span style="height: 2px; width: 6px; background: #25d366; border-radius: 1px;"></span>
              <span style="height: 2px; width: 6px; background: #4a90e2; border-radius: 1px;"></span>
              <span style="height: 2px; width: 6px; background: #ff5722; border-radius: 1px;"></span>
            </div>
          </div>

          <!-- NẮP ĐÁY THÂN MÁY VỚI VÍT 4 GÓC -->
          <div style="width: 100%; height: 22px; background: #f8f9fa; border-radius: 4px; border: 1px solid #e2e8f0; position: relative; display: flex; justify-content: space-between; align-items: center; padding: 0 3px;">
            <span style="height: 2px; width: 2px; background: #94a3b8; border-radius: 50%;"></span>
            <span style="font-size: 6px; font-weight: 900; color: #475569; letter-spacing: 0.5px;">SNA PRO</span>
            <span style="height: 2px; width: 2px; background: #94a3b8; border-radius: 50%;"></span>
          </div>

          <!-- CÁC CỔNG JACK CẮM CÁP / CÔNG TẮC DC ĐÁY MÁY -->
          <div style="position: absolute; bottom: -6px; display: flex; gap: 4px; z-index: -1;">
            <span style="width: 5px; height: 7px; background: #334155; border-radius: 0 0 2px 2px;"></span>
            <span style="width: 5px; height: 7px; background: #334155; border-radius: 0 0 2px 2px;"></span>
            <span style="width: 6px; height: 7px; background: #dc2626; border-radius: 0 0 2px 2px;"></span>
            <span style="width: 5px; height: 7px; background: #334155; border-radius: 0 0 2px 2px;"></span>
            <span style="width: 5px; height: 7px; background: #334155; border-radius: 0 0 2px 2px;"></span>
          </div>
        </div>
      </div>

      <!-- CỘT 3 (PHẢI): LƯỚI ĐIỆN & TẢI NHÀ -->
      <div style="width: 35%; height: 100%; display: flex; flex-direction: column; justify-content: space-between; align-items: flex-end; text-align: right; z-index: 2;">
        <div style="display: flex; align-items: center; gap: 6px; margin-top: 10px;">
          <div>
            <div style="font-size: 10px; color: #888;">Lưới điện</div>
            <div style="font-size: 12px; font-weight: 800; color: #4a90e2; line-height: 1.2;">${p_grid} <span style="font-size: 9px; color: #888; font-weight: 400;">W</span></div>
          </div>
          <ha-icon icon="mdi:transmission-tower" style="--mdc-icon-size: 26px; color: #4a90e2;"></ha-icon>
        </div>
        <div style="display: flex; align-items: center; gap: 6px; margin-bottom: 10px;">
          <div>
            <div style="font-size: 10px; color: #888;">Tiêu thụ</div>
            <div style="font-size: 12px; font-weight: 800; color: #ff5722; line-height: 1.2;">${p_load} <span style="font-size: 9px; color: #888; font-weight: 400;">W</span></div>
          </div>
          <ha-icon icon="mdi:home" style="--mdc-icon-size: 30px; color: #ff5722;"></ha-icon>
        </div>
      </div>

    </div>
  `;
]]]

cards.icon:
[[[
  const status = states['input_select.trang_thai_cua']?.state;

  if (entity.state === 'unavailable') {
    return 'mdi:garage-alert';
  }

  if (status === 'ĐANG MỞ' || status === 'ĐÃ MỞ') {
    return 'mdi:garage-open-variant';
  }

  if (status === 'ĐANG DỪNG') {
    return 'mdi:garage-alert-variant';
  }

  if (status === 'ĐANG ĐÓNG' || status === 'ĐÃ ĐÓNG') {
    return 'mdi:garage-variant';
  }

  return 'mdi:garage-variant';
]]]

custom_fields.status:
[[[
  const status = states['input_select.trang_thai_cua'];

  if (!status) return 'KHÔNG XÁC ĐỊNH';
  if (entity.state === 'unavailable') return 'MẤT KẾT NỐI';

  return status.state;
]]]

