[[[
  var p_today = parseFloat((states['sensor.luxpower_inverter_pv_pv_energy_today'] && states['sensor.luxpower_inverter_pv_pv_energy_today'].state != 'unavailable') ? states['sensor.luxpower_inverter_pv_pv_energy_today'].state : '0');
  var g_imp_today = parseFloat((states['sensor.luxpower_inverter_grid_energy_from_grid_today'] && states['sensor.luxpower_inverter_grid_energy_from_grid_today'].state != 'unavailable') ? states['sensor.luxpower_inverter_grid_energy_from_grid_today'].state : '0');
  var l_today = (p_today + g_imp_today).toFixed(1);

  var p_total = parseFloat((states['sensor.pv_energy_monthly'] && states['sensor.pv_energy_monthly'].state != 'unavailable' && states['sensor.pv_energy_monthly'].state != 'unknown') ? states['sensor.pv_energy_monthly'].state : ((states['sensor.luxpower_inverter_pv_pv_energy_total'] && states['sensor.luxpower_inverter_pv_pv_energy_total'].state != 'unavailable') ? states['sensor.luxpower_inverter_pv_pv_energy_total'].state : '0'));
  var g_imp_month = parseFloat((states['sensor.grid_energy_monthly'] && states['sensor.grid_energy_monthly'].state != 'unavailable' && states['sensor.grid_energy_monthly'].state != 'unknown') ? states['sensor.grid_energy_monthly'].state : ((states['sensor.luxpower_inverter_grid_energy_from_grid_total'] && states['sensor.luxpower_inverter_grid_energy_from_grid_total'].state != 'unavailable') ? states['sensor.luxpower_inverter_grid_energy_from_grid_total'].state : '0'));
  var l_total = (p_total + g_imp_month).toFixed(1);

  // TÍNH TIỀN ĐIỆN 6 BẬC EVN MỚI NHẤT
  var k_val = parseFloat(l_total) || 0;
  var cost = 0;
  if (k_val <= 50) {
    cost = k_val * 1984;
  } else if (k_val <= 100) {
    cost = 50 * 1984 + (k_val - 50) * 2050;
  } else if (k_val <= 200) {
    cost = 50 * 1984 + 50 * 2050 + (k_val - 100) * 2380;
  } else if (k_val <= 300) {
    cost = 50 * 1984 + 50 * 2050 + 100 * 2380 + (k_val - 200) * 2998;
  } else if (k_val <= 400) {
    cost = 50 * 1984 + 50 * 2050 + 100 * 2380 + 100 * 2998 + (k_val - 300) * 3350;
  } else {
    cost = 50 * 1984 + 50 * 2050 + 100 * 2380 + 100 * 2998 + 100 * 3350 + (k_val - 400) * 3460;
  }
  var l_money = Math.round(cost).toLocaleString('vi-VN');

  var l_power = (states['sensor.luxpower_inverter_load_power'] && states['sensor.luxpower_inverter_load_power'].state != 'unavailable') ? states['sensor.luxpower_inverter_load_power'].state : '0';

  return `
    <div style="display: flex; flex-direction: column; justify-content: space-between; height: 100%; width: 100%; box-sizing: border-box;">
      <div>
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; width: 100%;">
          <div style="display: flex; align-items: center; gap: 6px; background: rgba(255,87,34,0.15); padding: 4px 8px; border-radius: 10px; color: #ff5722; font-weight: 800; font-size: 11px;">
            <ha-icon icon="mdi:home-lightning-bolt" style="--mdc-icon-size: 15px; color: #ff5722;"></ha-icon> TIÊU THỤ
          </div>
          <img src="https://img.icons8.com/3d-fluency/94/home.png" style="height: 30px;" />
        </div>

        <div style="display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; margin-top: 6px; margin-bottom: 8px; width: 100%;">
          <div style="text-align: center;">
            <div style="font-size: 9px; color: #b38575; font-weight: 800;">HÔM NAY</div>
            <div style="font-size: 20px; font-weight: 800; color: #fff; margin-top: 2px; line-height: 1.1;">
              ${l_today} <span style="font-size: 10px; color: #aaa; font-weight: 400;">kWh</span>
            </div>
          </div>

          <div style="width: 1px; height: 42px; background: rgba(255,255,255,0.12);"></div>

          <div style="text-align: center;">
            <div style="font-size: 9px; color: #b38575; font-weight: 800;">THÁNG NÀY</div>
            <div style="font-size: 20px; font-weight: 800; color: #fff; margin-top: 2px; line-height: 1.1;">
              ${l_total} <span style="font-size: 10px; color: #aaa; font-weight: 400;">kWh</span>
            </div>
            <div style="font-size: 11px; color: #ffb74d; font-weight: 700; margin-top: 2px;">
              ~${l_money} đ
            </div>
          </div>
        </div>
      </div>

      <div style="background: rgba(0, 0, 0, 0.4); border-radius: 12px; padding: 7px 12px; display: flex; justify-content: center; align-items: center; gap: 8px; width: 100%; box-sizing: border-box;">
        <div style="font-size: 11px; font-weight: 600; color: #d0a495;">Công Suất Hiện Tại:</div>
        <div style="font-size: 17px; font-weight: 800; color: #ff5722;">${l_power} <span style="font-size: 11px; font-weight: 400; color: #aaa;">W</span></div>
      </div>
    </div>
  `;
]]]

