card.state_display:
[[[
  const sw = states['switch.cong_tac_nong_lanh'];
  const timer = states['timer.nong_lanh_20_phut'];

  if (sw?.state === 'unavailable') {
    return 'Còn --:-- sẽ tắt';
  }

  if (sw?.state !== 'on') {
    return 'Còn --:-- sẽ tắt';
  }

  if (!timer || timer.state !== 'active') {
    return 'Còn 20:00 sẽ tắt';
  }

  const finishesAt = timer.attributes.finishes_at;

  if (!finishesAt) {
    return 'Còn --:-- sẽ tắt';
  }

  const totalSeconds = Math.max(
    0,
    Math.ceil(
      (new Date(finishesAt).getTime() - Date.now()) / 1000
    )
  );

  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;

  return `Còn ${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')} sẽ tắt`;
]]]

